package ama.transcript;
import ama.task.*;import ama.contract.ExternalContracts.*;import ama.contract.TaskContracts.*;import ama.contract.IdentityContracts.*;import ama.contract.ConfigArchiveContracts.*;import ama.contract.ConfigArchiveContracts.Ref;import ama.canonical.*;import ama.config.*;import ama.model.*;import java.util.*;
import static ama.config.WireValues.*;import static ama.canonical.CanonicalValue.*;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Bounded reconstruction of an already recorded request. No source payload, POST, or send capability. */
public final class MinutesRecordedLookup {
 final JdbcExternalOperations.RecordedLookup capability;final javax.sql.DataSource source;
 final MinutesExternalPreparation issuer;final OperationToken token;final String taskId,manifest,requester,requestHash,payloadHash,key;final TaskSpec spec;
 private MinutesRecordedLookup(JdbcExternalOperations.RecordedLookup capability,javax.sql.DataSource source,MinutesExternalPreparation issuer,OperationToken token,String taskId,TaskSpec spec,String manifest,String requester,String requestHash,String payloadHash,String key){this.capability=capability;this.source=source;this.issuer=issuer;this.token=token;this.taskId=taskId;this.spec=spec;this.manifest=manifest;this.requester=requester;this.requestHash=requestHash;this.payloadHash=payloadHash;this.key=key;}
 public String executionId(){return token.executionId();}public String requestHash(){return requestHash;}public String payloadHash(){return payloadHash;}public String businessKey(){return key;}
 public void requireClient(ControlledMinutesClient client){issuer.requireClient(client);capability.require(source,token);}
 static Optional<MinutesRecordedLookup> prepare(MinutesExternalPreparation issuer,JdbcTranscriptAuthority authority,JdbcExternalOperations.RecordedLookup capability,OperationToken token){
  JdbcMinutesFactsReader.independent();capability.require(authority.dataSource(),token);require(token.executionNo()==1,PROVENANCE_UNAVAILABLE);var j=new org.springframework.jdbc.core.JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);
  var sizes=j.queryForList("SELECT task_id,OCTET_LENGTH(request_manifest) manifest_bytes FROM external_execution WHERE id=? AND operation_id=? AND execution_no=?",token.executionId(),token.operationId(),token.executionNo());require(sizes.size()==1&&sizes.getFirst().get("manifest_bytes") instanceof Number&&((Number)sizes.getFirst().get("manifest_bytes")).longValue()>0&&((Number)sizes.getFirst().get("manifest_bytes")).longValue()<=65536,PROVENANCE_UNAVAILABLE);String task=(String)sizes.getFirst().get("task_id");
  var rows=j.queryForList("SELECT e.request_manifest,e.request_hash,o.request_hash logical_hash,o.operation_kind,o.business_key,o.subject_kind,o.subject_id FROM external_execution e JOIN external_operation o ON o.id=e.operation_id WHERE e.id=? AND e.operation_id=? AND e.execution_no=1 AND e.task_id=? AND OCTET_LENGTH(e.request_manifest) BETWEEN 1 AND 65536",token.executionId(),token.operationId(),task);require(rows.size()==1,PROVENANCE_UNAVAILABLE);var row=rows.getFirst();var taskRows=j.queryForList("SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,priority,cancel_epoch,max_attempts FROM durable_task WHERE id=?",task);require(taskRows.size()==1,PROVENANCE_UNAVAILABLE);var spec=TranscriptReadGraph.spec(taskRows.getFirst());MinutesTaskDomainPolicy.shape(spec);require(spec.subject().equals(token.subject())&&spec.subject().id().equals(row.get("subject_id"))&&spec.subject().kind().equals(row.get("subject_kind")),PROVENANCE_UNAVAILABLE);
  require(ama.minutes.MinutesGenerateProducer.compute(spec.subject().id(),spec.input().id(),spec.inputFingerprint(),spec.businessVersion(),spec.cancelEpoch(),authority.canonicalBudget(),()->false).equals(spec.producerKey()),PROVENANCE_UNAVAILABLE);
  var inputs=j.queryForList("SELECT meeting_id,input_fingerprint,base_revision,prompt_version,model_config_version,scope,target_element_id,material_snapshot_id FROM generation_input WHERE id=?",spec.input().id());require(inputs.size()==1,PROVENANCE_UNAVAILABLE);var input=inputs.getFirst();var reconstructed=reconstruct((String)row.get("request_manifest"),spec,task,input,row,authority.canonicalBudget());String manifest=(String)row.get("request_manifest"),requester=reconstructed.requester(),hash=reconstructed.requestHash(),payload=reconstructed.payloadHash(),key=reconstructed.businessKey();
  var request=new MinutesRecordedLookup(capability,authority.dataSource(),issuer,token,task,spec,manifest,requester,hash,payload,key);
  boolean denied=authority.transactionRunner().required(()->{var actor=new Actor(requester,Status.ACTIVE,Set.of(ama.contract.IdentityContracts.Role.USER));var access=(ama.meeting.JdbcMeetingAccess)authority.meetingAccess();var ids=access.tryLockFactIdentities(actor,Set.of(requester),false).orElseThrow();var root=access.lockFactRoot(ids,spec.subject().id(),false).orElseThrow();String owner=j.queryForObject("SELECT owner_id FROM meeting WHERE id=?",String.class,spec.subject().id());require(requester.equals(owner),PROVENANCE_UNAVAILABLE);return !access.factAllowsBusiness(root,spec.cancelEpoch(),spec.businessVersion());});
  return denied?Optional.of(request):Optional.empty();
 }
 record Reconstruction(String requester,String requestHash,String payloadHash,String businessKey){}
 /** Complete bounded original manifest validation, shared by active and denied reconstruction. */
 static Reconstruction reconstruct(String manifest,TaskSpec spec,String task,Map<String,Object> input,Map<String,Object> row,ama.contract.MinutesContracts.CanonicalBudget canonicalBudget){
  byte[] bytes=manifest.getBytes(java.nio.charset.StandardCharsets.UTF_8);var value=BoundedModelJson.parse(bytes,65536);require(Arrays.equals(bytes,CanonicalJson.encode(value,65536,()->false)),PROVENANCE_UNAVAILABLE);var m=fields(value,"protocolVersion","providerId","modelIdentity","taskId","inputId","inputFingerprint","requesterId","logicalBusinessKey","payloadSha256","archiveIndexSha256","roots","base");
  literal(m.get("protocolVersion"),ControlledMinutesProtocol.VERSION);literal(m.get("providerId"),"CONTROLLED_HTTP_V1");literal(m.get("modelIdentity"),ControlledMinutesProtocol.MODEL);literal(m.get("taskId"),task);literal(m.get("inputId"),spec.input().id());literal(m.get("inputFingerprint"),spec.inputFingerprint());String requester=text(m.get("requesterId"));require(!requester.isEmpty()&&requester.length()<=255,PROVENANCE_UNAVAILABLE);String key="minutes:"+spec.input().id();literal(m.get("logicalBusinessKey"),key);String payload=text(m.get("payloadSha256"));hash(payload);hash(text(m.get("archiveIndexSha256")));var base=fields(m.get("base"),"businessVersion","cancelEpoch");require(ama.config.WireValues.number(base.get("businessVersion"))==spec.businessVersion()&&ama.config.WireValues.number(base.get("cancelEpoch"))==spec.cancelEpoch(),PROVENANCE_UNAVAILABLE);
  var refs=array(m.get("roots"));require(!refs.isEmpty()&&refs.size()<=128,PROVENANCE_UNAVAILABLE);Ref previous=null;var kinds=EnumSet.noneOf(ArtifactType.class);var identities=new HashSet<Identity>();for(var v:refs){Ref ref=ama.config.WireValues.ref(v);require(Set.of(ArtifactType.PROMPT_CONFIG,ArtifactType.MODEL_CONFIG,ArtifactType.PROCESSING_CONFIG,ArtifactType.REVIEW_HASH).contains(ref.artifactType()),PROVENANCE_UNAVAILABLE);if(previous!=null){int order=previous.artifactType().name().compareTo(ref.artifactType().name());require(order<0||order==0&&CanonicalValueCodec.compareUtf8(previous.version(),ref.version(),()->false)<0,PROVENANCE_UNAVAILABLE);}previous=ref;kinds.add(ref.artifactType());require(identities.add(ref.identity()),PROVENANCE_UNAVAILABLE);}
  require(kinds.containsAll(Set.of(ArtifactType.PROMPT_CONFIG,ArtifactType.MODEL_CONFIG,ArtifactType.PROCESSING_CONFIG)),PROVENANCE_UNAVAILABLE);
  require(spec.subject().id().equals(input.get("meeting_id"))&&spec.inputFingerprint().equals(input.get("input_fingerprint"))&&((Number)input.get("base_revision")).longValue()==spec.businessVersion()&&"FULL".equals(input.get("scope"))&&input.get("target_element_id")==null&&identities.stream().anyMatch(id->id.artifactType()==ArtifactType.PROMPT_CONFIG&&id.version().equals(input.get("prompt_version")))&&identities.stream().anyMatch(id->id.artifactType()==ArtifactType.MODEL_CONFIG&&id.version().equals(input.get("model_config_version"))),PROVENANCE_UNAVAILABLE);
  var envelope=object(field("logicalBusinessKey",m.get("logicalBusinessKey")),field("inputId",m.get("inputId")),field("inputFingerprint",m.get("inputFingerprint")),field("protocolVersion",m.get("protocolVersion")),field("modelIdentity",m.get("modelIdentity")),field("payloadSha256",m.get("payloadSha256")),field("roots",m.get("roots")));String hash=new CanonicalValueCodec().sha256(ama.minutes.contract.ContractValues.envelope("ama.minutes-model-request.v1","MODEL_REQUEST",envelope),canonicalBudget,()->false);require(hash.equals(row.get("request_hash"))&&hash.equals(row.get("logical_hash"))&&key.equals(row.get("business_key"))&&"MINUTES_GENERATE".equals(row.get("operation_kind")),PROVENANCE_UNAVAILABLE);
  return new Reconstruction(requester,hash,payload,key);
 }

}
